// Named procedural asset families; no remote textures, models or audio.
const assetDistricts={};function district(name,dir,scale){const g=anchor(dir.normalize(),1);g.name=name;g.scale.setScalar(scale);assetDistricts[name]=g;return g;}
const florist=district('Florist_District',new T.Vector3(.62,-.71,-.64),.11),flowerParts=[];
function flowerPart(name,c,x,y,z,w,h,d,delta){const o=box(florist,c,x,y,z,w,h,d);o.name=name;flowerParts.push({o,home:o.position.clone(),delta:new T.Vector3(...delta),delay:(flowerParts.length%7)*.09});return o;}
