for(let row=0;row<3;row++){flowerPart('Shelf_'+row,'#8c7358',0,.45+row*.55,-1,3.1,.08,.52,[0,row*.45,-.5]);for(let i=0;i<7;i++){const x=-1.3+i*.43,y=.65+row*.55;flowerPart('Pot_Interior_'+row+'_'+i,'#b98264',x,y,-1,.22,.28,.22,[x*.6,row*.6,-.5]);flowerPart('Flower_Interior_'+row+'_'+i,['#d997ac','#d6bc6e','#9cba82'][i%3],x,y+.22,-1,.24,.2,.24,[x*.6,row*.6,-.5]);}}
