// Shared-route railway: all trains reserve exclusive blocks before moving.
const railway=district('Railway_District',new T.Vector3(.85,.38,-.65),.11),railBlocks=12,railOwners=Array(12).fill(-1),railTrains=[],railSignals=[];
function miniRail(u,branch=0){const a=u/railBlocks*Math.PI*2,r=4+(branch?Math.sin((u%1)*Math.PI)*.85:0);return new T.Vector3(Math.cos(a)*r,.22+Math.sin(a*2)*.12,Math.sin(a)*r*.7);}
for(let b=0;b<railBlocks;b++){for(let lane=0;lane<(b%3===0?2:1);lane++){const pts=[];for(let k=0;k<=24;k++)pts.push(miniRail(b+k/24,lane));const c=new T.CatmullRomCurve3(pts);mesh(new T.TubeGeometry(c,30,.045,5,false),'#9c9479',railway);}const p=miniRail(b);box(railway,'#727e69',p.x,.55,p.z,.05,.6,.05);const lamp=ball(railway,'#84bc8c',p.x,.9,p.z,.10);lamp.material=mat('#84bc8c').clone();railSignals.push(lamp);}
for(let i=0;i<3;i++){const g=new T.Group();g.name='Train_'+(i+1);railway.add(g);box(g,['#c67e65','#678b79','#bca163'][i],0,.18,0,.4,.32,.72);box(g,'#e8d6b0',0,.39,0,.43,.09,.78);box(g,'#789c9c',0,.24,.37,.3,.16,.02);railOwners[i*4]=i;railTrains.push({g,block:i*4,progress:0,lane:0,speed:.13+i*.013,waiting:false,laps:0});}
function railStep(dt){for(let i=0;i<3;i++){const train=railTrains[i],next=(train.block+1)%railBlocks;train.waiting=train.progress>=.50&&railOwners[next]!==-1&&railOwners[next]!==i;if(!train.waiting){if(train.progress>=.50)railOwners[next]=i;train.progress+=dt*train.speed;if(train.progress>=1){railOwners[train.block]=-1;train.block=next;railOwners[next]=i;train.progress-=1;train.laps++;train.lane=train.block%3===0?train.laps%2:0;}}const p=miniRail(train.block+train.progress,train.lane);train.g.position.copy(p);train.g.lookAt(miniRail(train.block+train.progress+.01,train.lane));}railSignals.forEach((l,i)=>l.material.color.set(railOwners[i]<0?'#84bc8c':'#d58169'));}
// Mountain hamlet: timber halls, stone watchtower and snow-edged peaks.
const village=district('Highland_Village',new T.Vector3(-.8,.57,-.4),.11);for(let i=0;i<7;i++){const x=(i%3-1)*1.7,z=Math.floor(i/3)*1.6-1.5;box(village,'#a38f70',x,.5,z,1.25,1,1);const roof=mesh(new T.ConeGeometry(1.1,.8,4),'#626e6e',village);roof.rotation.y=Math.PI/4;roof.position.set(x,1.38,z);box(village,'#efcc87',x,.6,z+.51,.25,.3,.02);}for(let i=0;i<4;i++){const g=new T.Group();village.add(g);g.position.set(-3+i*2,0,-3);rockSpire(g,2.5+(i%2),1,'#89938b',true);}
// Lava traces follow the existing volcano's surface; rescue boats circle a small local basin.
const rescue=district('Volcano_Rescue',offset(biomes.volcano.dir,-.27,.16),.12),lavaBits=[];box(rescue,'#7f9991',0,.01,0,3,.05,2);const rescueBoat=new T.Group();rescueBoat.name='Rescue_Boat';rescue.add(rescueBoat);box(rescueBoat,'#8b674b',0,.15,0,.9,.18,.4);box(rescueBoat,'#ddbd80',0,.34,0,.4,.25,.32);branch(rescueBoat,'#a18b60',[0,.4,0],[0,1,0],.025);box(rescueBoat,'#bf7559',.2,.77,0,.35,.4,.03);
for(let i=0;i<35;i++){const d=offset(biomes.volcano.dir,-.05+i*.003,-.03-i*.006),g=anchor(d,1);const m=ball(g,'#df8d46',0,.07,0,.024,.012,.04);m.material=mat('#df8d46',{emissive:'#ce531e',emissiveIntensity:.7});lavaBits.push(m);}
function animateAssets(t,dt){railStep(dt);lavaBits.forEach((m,i)=>{m.scale.y=.012*(1+.35*Math.sin(t*3-i*.7));m.position.y=.07+.006*Math.sin(t*2-i*.4);});rescueBoat.position.set(Math.sin(t*.22)*.9,.08,Math.cos(t*.22)*.5);rescueBoat.rotation.y=t*.22+Math.PI/2;}
window.planetAssets={districts:assetDistricts,flowerParts,railTrains,railOwners,railStep,animate:animateAssets,focus(name){const g=assetDistricts[name];if(!g)return;window.manhattanExplorer.exit();goal=new T.Quaternion().setFromUnitVectors(g.position.clone().normalize(),new T.Vector3(0,.08,1).normalize());distance=10.6;}};

